INSERT INTO transfer_targets VALUES(10,'AVL','2026-summer','Modou Kéba Cissé','시세','시세',57,1944705,'LASK → Aston Villa','CB','RCB','CONFIRMED',NULL,'001100013201476027X812666',60.89999999999999858,31.19999999999999929,29,7.099999999999999645,'cb_defender','Balanced','cb_bpd','Aggressive',0.8830000000000000071,'CONFIRMED incoming: pre-contract signed summer 2025, joins for 2026/27 after a season at LASK. Measured: right-of-centre CB (60.9,31.2), Ball-Playing Defender/Aggressive fit 0.89 — same fit family as Konsa (0.88). Natural RCB cover/heir; Austrian Bundesliga level caveat. [2026-07-15 재확인] RotoWire: 공식 합류 확인(사전계약, LASK에서 2026년 여름 발효). [2026-07-15 3축+스탯 — 유지] 6경기: kp 0·xA .01·듀얼 3.8·태클 1.5·패스 84% — 진전 산출 없는 수비형, cb_defender/Balanced 처방 유지(움직임은 bpd/Aggressive .89로 콘사형 스텝아웃 — 기능축 우선). LASK 리그 수준 캐비앗. [2026-07-28 FC26 통합 확인] 숙련 cb_defender+·cb_stopper+ — bpd 마커 없음, 기능축 처방(cb_defender/Balanced)을 FC26이 지지 — 확정.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 29경기.  커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(13,'AVL','2026-summer','Alysson','알리송',NULL,59,1631879,'Aston Villa (2026-01, Grêmio €10M)','RW','RM','OWNED',NULL,'001331015X001370003500013',83.20000000000000284,59.70000000000000284,22,6.879999999999999894,'wm_winger','Balanced','wm_widemid','Build-Up',0.8329999999999999627,'ALREADY OWNED: joined from Grêmio for €10M in January 2026; young (2006) right winger not yet in the analysis roster. Measured: genuine wide-right (83.2,59.7) — the squad''s only natural touchline RW; fit Inside Forward/Balanced 0.85. Prescription Winger/Attack to use his width+pace profile distinct from McGinn/Bowen half-space types. [2026-07-15 3축+스탯 — 유지] 6경기: xG .10·xA .03·kp .3·듀얼 3.7·드리블 1.0 — 창조 산출 미성숙 직선 윙어, winger/Attack 처방 유지(움직임 최근접은 insidefwd/Balanced .847). [2026-07-29 우측 브리프 정합 검증] 디아비 템플릿 코사인 .839, 침투 서명 전방 0.54·자기진영 0.23(하지무사·음바예보다 낮음 = 침투 빈도 열위), 터치라인 열 0.60 = 스쿼드 유일 천연 터치라인 RW. 함의: 브리프를 부분 충족하는 보유 자원이라 "우측이 절대 공백은 아니다"는 협상 레버리지. 19세로 주전 고정은 리스크.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 22경기.  커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(30,'AVL','2026-summer','Tammy Abraham','타미 아브라함',NULL,60,610766,'Aston Villa','ST','ST','OWNED',NULL,'239324777256X732212211410',47.39999999999999858,59.0,25,6.950000000000000177,'st_target','Attack','st_false9','Attack',0.6430000000000000159,'ALREADY OWNED: 2026-01-27 베식타슈에서 ~£18m로 빌라 복귀(1일 만에 재이적), 그 시즌 유로파리그 우승. 여름 루머 대상이 아니라 보유 선수(알리송과 동일 케이스) — 사용자 요청으로 OWNED ST 옵션으로 편입. 실측(반시즌 통틀어 45분+ 4경기 전부 ST): 중앙-약간좌측·깊은 풋프린트 (47.4,59.0), 평균 6.85. 최근접 st_false9/Attack 0.52 — 왓킨스(st_advanced 자기커널)·기라시 0.80·브로베이 0.75·파르도 0.87보다 명확히 낮음. 처방은 타깃/홀드업 아키타입 반영 st_target/Attack. 표본 캐비앳: 왓킨스의 로테이션 백업이라 45분+ 경기가 반시즌 4경기뿐이고 전부 교체 출전(추격 상황 드롭) → 깊은 편향된 풋프린트, 선발 표본 아님. [2026-07-15 3축+스탯 — 유지] 6경기: xG .25·3골·kp 1.0·드리블 0 — 타깃형 피니셔, st_target/Attack(공중 플랜B, obs#19) 유지.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 25경기.  커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(77,'AVL','2026-summer','Johan Manzambi','만잠비','만잠비',55,1518931,'SC Freiburg','CM','LDM','CONFIRMED',NULL,'33423X9565897636965322311',43.60000000000000142,51.79999999999999716,56,7.200000000000000177,'dm_dlp','Roaming','dm_dlp','Roaming',0.7129999999999999672,'완전 box-to-box, 중앙 전역 커버(온아나 대체). 실측 6경기(분데스리가, 363pt) 중심 tool(44,52). 커널 fit LDM dm_dlp/Roaming 0.812 (RDM는 0.544로 약함 → 좌중앙 성향, LDM 전용). 평균 7.62 최상. [2026-07-14 확정] 빌라 합류 확정(사용자 확인). [2026-07-15 재확인] Romano "here we go": €60m+ 구두합의, 개인조건 완료. 뉴캐슬 £49m 구두합의를 히잭. 아직 공식 발표(메디컬) 전 단계. [2026-07-15 3축+스탯 — 유지] 6경기: 듀얼 7.5(후보군 1위)·xG .18·xA .16·태클 1.8·평점 7.40 — 박투박+창조 겸비(오나나 공백 임무에도 부합), dlp/Roaming 유지. [2026-07-17 재확인] 메디컬 완료(7/16), Romano "몇 시간 내 발표". Visit Rwanda 스폰서 관련 잡음(DRC 가족사) 해소, 5년 계약 — 클럽 레코드 £50m+. [2026-07-18 재확인] 공식 발표 완료(7/17 저녁) — £59.5m(€70m) 클럽 레코드, 장기계약. 뉴캐슬 하이잭 최종 성사. [2026-07-21 멀티포지션] CAM(대표팀 전진 실측 0.817)·LM(재배치 0.700) 행 추가 — 슬롯별 별도 그리드 참조. [2026-07-28 FC26 통합 확인] LDM: 숙련 dm_dlp+·cm_dlp+가 처방과 일치 — 확정. 테크니컬 PS·드리블85.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 56경기. 클럽(프라이부르크) 44경기 통합 — 딥 역할 표본 커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(91,'AVL','2026-summer','João Palhinha',NULL,'팔리냐',75,364612,'Bayern Munich','DM','LDM','HIGH','2026-08-12','012113536536797368X712431',57.0799999999999983,44.96000000000000085,34,7.160000000000000142,'dm_dlp','Roaming','dm_dlp','Roaming',0.7089999999999999636,'바이에른과 시즌 로그론 + €25m 의무구매옵션 가능성 합의, 잉글랜드 이동 중(오나나 부상 공백 메우기). 온나나 십자인대 부상, 틸레만스 맨유行으로 보강 필요. [2026-07-27 21시 최신화] 로마노/애슬레틱(Tanswell) 경유: 팔리냐가 잉글랜드로 이동해 임대(+콜옵션 €25m) 마무리 단계 — 벤피카를 제치고 빌라가 사실상 확보. 다만 Tanswell은 "완전히 무산된 건 아니지만 빌라가 다른 일들로 바빠 잠시 정체"라고 톤 조절. 바이에른은 매각 강력 희망(€100m 펀드 확보 목적). [2026-07-28 FC26 통합 확인] 숙련 dm_holding+(수비/볼위닝/로밍)가 기능축 처방과 정확 일치 — 확정. DEF83/PHY84/공격성91/태클85·슬라이딩태클/브루저 PS. 캐비앗: 네거티브 PS "부상에 취약함". [2026-07-29 14시 재확인 — HIGH 유지] Plettenberg(Sky DE): 7/19 "영국행·합의" 보도 반박 — 합의 없음, 프리시즌 바이에른 합류. 현 상태: 빌라=대여+옵션 고수 vs 바이에른=€25m 완전이적 요구 교착. BILD "빌라가 바이에른의 최유력 매각처". 사우디·터키 관심 있으나 선수는 유럽 잔류 희망(가족). [경쟁구도 2026-07-30] 빌라 우위 — 경쟁 대안(벤피카·스포르팅)은 마르쿠 실바 재결합 등 동기는 있으나 €25m 지불 능력이 없고, 사우디·터키 공식 오퍼는 선수가 거부. 바이에른 SD Freund가 7/28 공개 발언("다음 단계는 다른 곳에서")으로 매각 기조 확정, BILD는 빌라를 최유력 매수처로 서술. 교착 지점은 클럽 경쟁이 아니라 구조(임대+옵션 vs 완전 €25m)와 선수 본인 결정. 선수 선호는 자녀 거주지(포르투갈) 근접이지만 자금이 그 선호를 봉쇄. [경쟁구도 2026-08-01 — 빌라 우위 → **대등**으로 하향] 뉴캐슬 참전: ESPN Brasil(Bruno Andrade 기명)이 뉴캐슬이 브루누 기마랑이스 아스날행 대비 미드필더 2인과 협상 중이며 그중 하나가 팔리냐라고 보도. 뉴캐슬은 기마랑이스 매각 ~€93m(+토날리 €117m 기수령)으로 **지불력이 빌라 £40m 상한(Tanswell)보다 명확히 우위**. 바이에른 측: Falk — 바이에른이 더는 합의를 자신하지 못하며, 선수 본인이 "요구액 미인하 시 잔류도 감수"로 **레버리지를 쥠**. Eberl이 매각 대상 3인에 공개 포함, 완전이적 **€30m 근접액 요구**(07-30 €25m에서 상향). 구조 교착(빌라 임대+옵션 vs 바이에른 완전이적)은 불변. §2-1 보정표상 "경쟁 클럽 우위"가 아니라 "대등"이므로 **등급은 HIGH 유지**. [2026-08-02 경쟁구도 재판정 — 대등 → **빌라 우위**로 되돌린다] ⚠️ **어제(08-01) 하향은 과잉 해석이었다.** 근거로 쓴 ESPN Brasil(Bruno Andrade) 기사는 뉴캐슬이 기마랑이스 대체 **숏리스트 2인**을 추렸고 그중 하나가 팔리냐라는 내용까지이며, **협상 단계라고 쓰지 않았다** — 나는 "지불력 우위(€93m)"를 "단계 우위"로 읽었다. 오늘 독립 확인 결과 **뉴캐슬의 입찰 보도는 없고 관심·숏리스트 단계**이며, 빌라는 **수 주간 바이에른과 협상 중**(돌파구 없음)이다. 단계 비교(협상 > 관심)에서 빌라가 앞선다. ⚠️ 단 오늘 검색은 **빌라의 공식 입찰(formal bid) 제출도 확인하지 못했다** — 스캔 에이전트의 "빌라만 공식 입찰" 서술은 채택하지 않는다. 교착 요인 불변: 빌라 임대+옵션 vs 바이에른 완전이적 €30m 근접, Falk "바이에른이 더는 합의를 자신하지 못한다", 선수는 잔류도 감수 + 사우디 오퍼 거절. [경쟁구도 2026-08-03 22시 — 뉴캐슬 항 하향] ⭐ **에디 하우가 2026-07-31 뉴캐슬 감독직에서 사퇴했다**(구단 공식 발표 + Sky Sports + ESPN = 1티어 3중). 브리스톨 시티전 1-4 패배 직후이고, 사유는 개인 재충전이나 배경으로 **어려운 여름 이적창**(토날리·고든 매각)이 병기된다. 후임 미임명(Jaissle 유력, "advanced stage"), 개막(8/23 리버풀)까지 25일. → **감독 부재 상태의 중원 숏리스트는 집행력이 없다**. 다만 반대 방향 요인이 병존한다: 기마랑이스→아스날 €93m이 성사되면 **자금은 오히려 늘어난다**. 정확한 서술은 **"자금은 늘고 집행 주체는 사라진 상태"**다. ⚠️ 이 사실은 08-03 09시·21시 두 섹션이 모두 놓쳤다 — 경쟁 클럽 링크를 **숏리스트 등재 여부로만** 추적하면 상대 구단의 **제도적 집행력 변화**를 놓친다는 사례로 남긴다. 빌라 등급 HIGH·단계는 불변(병목은 여전히 바이에른의 완전이적 €25~30m 고수). [2026-08-06 22시 갱신 — HIGH 유지, 발행일 확정] 09시에 "Bild 보도·발행일 미확정"으로 남겨둔 건이 확정됐다: Sport1(2026-08-06)·Sport BILD가 바이에른의 **€25m 요구를 빌라가 거부**해 재정 조건에서 교착이라고 보도. 신규 사실 — 양 구단이 **08-07 홍콩 카이탁 친선전(Audi Football Summit)을 계기로 대면 협상**을 갖는다. [반대 신호] 팔리냐 본인이 Abendzeitung에 "바이에른에서 자리를 지키는 것이 계획"이라 발언(단, 측근은 오퍼 청취 지속·바이에른 26/27 1군 명단 제외·스포르팅 디렉터 Freund도 장기 계획 밖임을 인정). 단계는 "협상(교착)" 유지 — 오퍼 제출·개인합의 보도 0건이라 상향 불가. [2026-08-07 09시 재확인 — HIGH 유지, 협상 미개최] 어제 예고된 홍콩 대면 협상은 **아직 열리지 않았다** — 친선전 킥오프가 08-07 14:00 CEST(21:00 KST)이고 독일 매체는 협상을 "경기 전후"로 예고했다. 즉 결과는 오늘 21시 회차의 대상이다(Sport1도 "결과는 아직 없다"고 명시). **08-06 이후 신규 사실 2건**: ⑴ **Eberl(바이에른 단장)이 팔리냐·Boey·Zaragoza에 대해 "바이에른에 미래는 없다"고 공개 발언** — 08-06의 Freund 인정보다 강한 공식 톤. ⑵ **임대+옵션·임대+의무매입 등 대안 구조도 이미 시도됐으나 합의 실패** — 교착이 총액뿐 아니라 구조 협상까지 소진된 상태다. 선수 입장은 변화 없음(잔류가 계획, 측근은 오퍼 청취 지속). 콤파니 중원 서열은 키미히·파블로비치·비쇼프·바라 은디아예. ⚠️ 발행일 함정 회피 1건: givemesport "Villa handed huge boost"(Falk/BILD 경유, 바이에른 호가 인하·임대 수용 가능성)는 **2026-07-21자**라 신선한 진전이 아니다. [2026-08-08 09시 재확인] 홍콩 친선전(08-07, 바이에른 2-1 승) 종료 후 빌라 SD Damian Vidagany가 Sport Bild에 직접 발언: "We are in talks, but there is currently no agreement." 바이에른 요구 €20-25m, 여전히 가격차 교착 — 단계 진전 없음. HIGH 유지. [2026-08-09 09시 재확인 — HIGH 유지] 빌라가 임대+의무매입옵션(단계적 지불) 구조를 대안으로 모색 중이나 바이에른은 완전이적(€25m) 우선 — 구조 교착 그대로. 선수 본인은 "요구액 인하 없으면 잔류도 감수"라는 입장 유지, 뮌헨 잔류 시 연봉 €10m+보너스 €2m 부담이 빌라 PSR에 걸림돌이라는 재정 분석 추가(신규 사실 아님, 정황 보강). 홍콩 대면협상 이후 추가 협상 진전 보도 없음. [2026-08-10 09시 재확인 — HIGH 유지] 단계·구조 전부 불변(빌라=1년 임대 스톱갭 선호 vs 바이에른=완전이적 €25m 고수). Vidagany 공식 발언 "협상 중이나 현재 합의 없음"이 최신 상태 그대로. [경쟁구도 신규] 뉴캐슬이 팔리냐 경쟁에 참전한다는 보도가 등장 — 단계는 관심 수준이고 빌라는 구단 공식 확인 협상 단계라 §2-1상 빌라 우위 유지, 등급 보정 없음. ⚠️[2026-08-10 자기정정] 이 회차의 갱신 내용은 **발행일 확정 실패**다 — Moretto 건은 TransferFeed "1h ago" 스탬프(수집 시각이지 발행 시각이 아님, §1)에만 근거하고 원문 날짜를 잡지 못했다. §2-0에 따라 last_news_date를 08-09로 되돌린다(STALE 시계는 확정된 보도일로만 움직인다). [2026-08-10 21시 — 경쟁 강도 하향 정정] 어제 기록한 "뉴캐슬 참전"의 실체가 드러났다: **뉴캐슬의 1순위는 마르세유의 Højbjerg이고 팔리냐는 그 대안으로 거론된 것**이다. 즉 뉴캐슬은 팔리냐를 주 타깃으로 쫓고 있지 않다 → §2-1 경쟁 강도를 한 단계 낮춰 읽어야 하며 **빌라 우위가 더 명확**해졌다. 단계는 여전히 불변(Vidagany "협상 중, 합의 없음", 가격 €25m·구조 임대vs완전 교착). ⚠️ 신규 서술: 협상이 **08-12 PSG 슈퍼컵 전에 마무리되지 않을 수 있다**는 전망. [2026-08-10 20시 — ⚠️ 이 rationale 첫 문장("€25m 의무구매옵션 가능성 합의, 잉글랜드 이동 중")은 07월 서사이며 현재 상태가 아니다. 후속 대괄호 항목들이 정본이다.] 사용자 제보("임대 이적 마무리 기사")를 §2-0으로 추적한 결과 원출처는 **A Bola 2026-07-17 19:15 「Palhinha a um passo do Aston Villa」**(기사 ID 2026071718151506424가 발행시각 인코딩)이며, 본문은 "토요일 잉글랜드로 이동해 합의를 마무리할 예정"이다. **그 이동도 합의도 일어나지 않았다** — 이미 Plettenberg(Sky DE)가 07-29에 같은 계열 보도(7/19 영국행·합의)를 반박했고 팔리냐는 바이에른 프리시즌에 합류했다. 즉 이 서사는 **24일 된 무산 건**이고, 재검색 시 상위 노출되므로 재순환 위험이 높다. 병기 확인: 같은 A Bola 계열의 벤피카 대안 구조(임대료 €10m + 의무매입 €15m)는 **bolanarede 2026-07-15**자이고 "제출"이 아니라 "제출 예정"이었다 — 이후 벤피카는 지불력 부족으로 탈락했다(07-30 판정). **현 상태 불변**: Vidagany 공식 "협상 중, 합의 없음"(08-07~08), 바이에른 €25m 완전이적 고수, 구조 교착. 오퍼 제출·개인합의·메디컬 보도 전부 0건. **HIGH 유지, last_news_date 갱신 없음**(신규 발행 확정 원문 없음). | [2026-08-12] HIGH 유지. 교착 지점이 **거래 구조**로 특정됐다 — 빌라는 **매입 옵션부 임대**(토트넘 방식) 선호, 바이에른은 **영구 이적** 선호. The Athletic(1티어) 기준 바이에른 호가 **€30m** 유지. [경쟁구도] 뉴캐슬·벤피카 경쟁 중 TEAMtalk 기준 **빌라 선두**. 오퍼·개인합의·메디컬 전부 0건. 공식 사유는 오나나 ACL 시즌 아웃(Vidagany 발언 근거). [2026-08-13] ⭐ **개인 조건은 이미 완전 합의**(Plettenberg/Sky Germany, 2티어) — 어제 "개인합의 0건"으로 적은 것을 정정한다. 막힌 지점은 **거래 구조 하나**로 좁혀졌다: 빌라의 임대+매입옵션 제안을 **바이에른이 거부**하고 영구 이적을 고수한다. 금액 소스 갈림 — Sport BILD €25m vs The Athletic 계열 €30m. Kerry Hau(Sky): 선수 본인이 콤파니 체제에서 전망이 없다고 판단해 오퍼를 구체 검토 중. [경쟁구도] 뉴캐슬·벤피카·스포르팅 대비 **빌라 선두 유지**. 오나나 ACL 시즌아웃이 빌라 측 공식 사유로 계속 인용된다. [2026-08-13 정형값 교정] player_matches의 45분+·hit_points>=15 전체 34경기(2750분)를 core.aggregate로 재집계. LDM 슬롯 제한 argmax는 dm_dlp/Roaming .709. 종전 6경기 값과 산문만 갱신된 불일치를 해소했다.','https://www.transferfeed.com/clubs/aston-villa/15; Record(PT); GiveMeSport; SportsMole ; Plettenberg/Sky DE via onefootball·readastonvilla (2026-07-24, 재검증 07-26); Sports Mole; Yahoo Sports/Bavarian Football Works("on verge"); Jacob Tanswell(Athletic, 팟캐스트); CaughtOffside ; https://www.sport1.de/news/transfermarkt/2026/08/fc-bayern-entscheidet-sich-der-palhinha-poker-in-hongkong (2026-08-06) ; https://bulinews.com/bayern-and-aston-villa-hold-palhinha-talks-after-pre-season-friendly (Sport BILD 경유) ; https://fcbinside.de/2026/08/06/testspiel-wird-zur-transfer-buehne-jetzt-kommt-bewegung-in-den-palhinha-poker/ ; https://www.90min.de/palhinha-poker-vor-neuer-wende-bayern-testet-gegen-interessenten','HIGH 유지 — 임대+콜옵션 구조로 사실상 합의 임박, 톤다운 코멘트 있으나 실행 단계 진입. / [2026-08-03] 경쟁 축 캐비앗: 뉴캐슬은 감독 공백으로 집행력 부재 · 자금은 증가 가능 — 두 방향이 상쇄돼 순효과는 미확정. | [실측 전수 완료 2026-08-12] 2026-08-12 전수 실측(SofaScore 25/26). 종전 6경기 표본을 대체하지 않고 추가한다(불변규칙 2). ⚠️ 표본은 **이전/현 소속 클럽**의 것이고 우리 팀 전술이 아니다(obs#157·#158). tool_x 57.1로 우중앙. RDM(.786) > LDM(.709)이라 **RDM 슬롯이 더 맞는다**. 표본은 바이에른. 45분+ 34경기(2750분) 집계. 종전 6경기 표본 dm_widehalf/Build-Up 0.709 → dm_dlp/Roaming 0.786.');
INSERT INTO transfer_targets VALUES(92,'AVL','2026-summer','João Palhinha',NULL,'팔리냐',75,364612,'Bayern Munich','DM','RDM','HIGH','2026-08-12','012113536536797368X712431',57.0799999999999983,44.96000000000000085,34,7.160000000000000142,'dm_dlp','Roaming','dm_dlp','Roaming',0.7860000000000000319,'바이에른과 시즌 로그론 + €25m 의무구매옵션 가능성 합의, 잉글랜드 이동 중(오나나 부상 공백 메우기). 온나나 십자인대 부상, 틸레만스 맨유行으로 보강 필요. [2026-07-27 21시 최신화] 로마노/애슬레틱(Tanswell) 경유: 팔리냐가 잉글랜드로 이동해 임대(+콜옵션 €25m) 마무리 단계 — 벤피카를 제치고 빌라가 사실상 확보. 다만 Tanswell은 "완전히 무산된 건 아니지만 빌라가 다른 일들로 바빠 잠시 정체"라고 톤 조절. 바이에른은 매각 강력 희망(€100m 펀드 확보 목적). [2026-07-28 FC26 통합 확인] 숙련 dm_holding+(수비/볼위닝/로밍)가 기능축 처방과 정확 일치 — 확정. DEF83/PHY84/공격성91/태클85·슬라이딩태클/브루저 PS. 캐비앗: 네거티브 PS "부상에 취약함". [2026-07-29 14시 재확인 — HIGH 유지] Plettenberg(Sky DE): 7/19 "영국행·합의" 보도 반박 — 합의 없음, 프리시즌 바이에른 합류. 현 상태: 빌라=대여+옵션 고수 vs 바이에른=€25m 완전이적 요구 교착. BILD "빌라가 바이에른의 최유력 매각처". 사우디·터키 관심 있으나 선수는 유럽 잔류 희망(가족). [경쟁구도 2026-07-30] 빌라 우위 — 경쟁 대안(벤피카·스포르팅)은 마르쿠 실바 재결합 등 동기는 있으나 €25m 지불 능력이 없고, 사우디·터키 공식 오퍼는 선수가 거부. 바이에른 SD Freund가 7/28 공개 발언("다음 단계는 다른 곳에서")으로 매각 기조 확정, BILD는 빌라를 최유력 매수처로 서술. 교착 지점은 클럽 경쟁이 아니라 구조(임대+옵션 vs 완전 €25m)와 선수 본인 결정. 선수 선호는 자녀 거주지(포르투갈) 근접이지만 자금이 그 선호를 봉쇄. [경쟁구도 2026-08-01 — 빌라 우위 → **대등**으로 하향] 뉴캐슬 참전: ESPN Brasil(Bruno Andrade 기명)이 뉴캐슬이 브루누 기마랑이스 아스날행 대비 미드필더 2인과 협상 중이며 그중 하나가 팔리냐라고 보도. 뉴캐슬은 기마랑이스 매각 ~€93m(+토날리 €117m 기수령)으로 **지불력이 빌라 £40m 상한(Tanswell)보다 명확히 우위**. 바이에른 측: Falk — 바이에른이 더는 합의를 자신하지 못하며, 선수 본인이 "요구액 미인하 시 잔류도 감수"로 **레버리지를 쥠**. Eberl이 매각 대상 3인에 공개 포함, 완전이적 **€30m 근접액 요구**(07-30 €25m에서 상향). 구조 교착(빌라 임대+옵션 vs 바이에른 완전이적)은 불변. §2-1 보정표상 "경쟁 클럽 우위"가 아니라 "대등"이므로 **등급은 HIGH 유지**. [2026-08-02 경쟁구도 재판정 — 대등 → **빌라 우위**로 되돌린다] ⚠️ **어제(08-01) 하향은 과잉 해석이었다.** 근거로 쓴 ESPN Brasil(Bruno Andrade) 기사는 뉴캐슬이 기마랑이스 대체 **숏리스트 2인**을 추렸고 그중 하나가 팔리냐라는 내용까지이며, **협상 단계라고 쓰지 않았다** — 나는 "지불력 우위(€93m)"를 "단계 우위"로 읽었다. 오늘 독립 확인 결과 **뉴캐슬의 입찰 보도는 없고 관심·숏리스트 단계**이며, 빌라는 **수 주간 바이에른과 협상 중**(돌파구 없음)이다. 단계 비교(협상 > 관심)에서 빌라가 앞선다. ⚠️ 단 오늘 검색은 **빌라의 공식 입찰(formal bid) 제출도 확인하지 못했다** — 스캔 에이전트의 "빌라만 공식 입찰" 서술은 채택하지 않는다. 교착 요인 불변: 빌라 임대+옵션 vs 바이에른 완전이적 €30m 근접, Falk "바이에른이 더는 합의를 자신하지 못한다", 선수는 잔류도 감수 + 사우디 오퍼 거절. [경쟁구도 2026-08-03 22시 — 뉴캐슬 항 하향] ⭐ **에디 하우가 2026-07-31 뉴캐슬 감독직에서 사퇴했다**(구단 공식 발표 + Sky Sports + ESPN = 1티어 3중). 브리스톨 시티전 1-4 패배 직후이고, 사유는 개인 재충전이나 배경으로 **어려운 여름 이적창**(토날리·고든 매각)이 병기된다. 후임 미임명(Jaissle 유력, "advanced stage"), 개막(8/23 리버풀)까지 25일. → **감독 부재 상태의 중원 숏리스트는 집행력이 없다**. 다만 반대 방향 요인이 병존한다: 기마랑이스→아스날 €93m이 성사되면 **자금은 오히려 늘어난다**. 정확한 서술은 **"자금은 늘고 집행 주체는 사라진 상태"**다. ⚠️ 이 사실은 08-03 09시·21시 두 섹션이 모두 놓쳤다 — 경쟁 클럽 링크를 **숏리스트 등재 여부로만** 추적하면 상대 구단의 **제도적 집행력 변화**를 놓친다는 사례로 남긴다. 빌라 등급 HIGH·단계는 불변(병목은 여전히 바이에른의 완전이적 €25~30m 고수). [2026-08-06 22시 갱신 — HIGH 유지, 발행일 확정] 09시에 "Bild 보도·발행일 미확정"으로 남겨둔 건이 확정됐다: Sport1(2026-08-06)·Sport BILD가 바이에른의 **€25m 요구를 빌라가 거부**해 재정 조건에서 교착이라고 보도. 신규 사실 — 양 구단이 **08-07 홍콩 카이탁 친선전(Audi Football Summit)을 계기로 대면 협상**을 갖는다. [반대 신호] 팔리냐 본인이 Abendzeitung에 "바이에른에서 자리를 지키는 것이 계획"이라 발언(단, 측근은 오퍼 청취 지속·바이에른 26/27 1군 명단 제외·스포르팅 디렉터 Freund도 장기 계획 밖임을 인정). 단계는 "협상(교착)" 유지 — 오퍼 제출·개인합의 보도 0건이라 상향 불가. [2026-08-07 09시 재확인 — HIGH 유지, 협상 미개최] 어제 예고된 홍콩 대면 협상은 **아직 열리지 않았다** — 친선전 킥오프가 08-07 14:00 CEST(21:00 KST)이고 독일 매체는 협상을 "경기 전후"로 예고했다. 즉 결과는 오늘 21시 회차의 대상이다(Sport1도 "결과는 아직 없다"고 명시). **08-06 이후 신규 사실 2건**: ⑴ **Eberl(바이에른 단장)이 팔리냐·Boey·Zaragoza에 대해 "바이에른에 미래는 없다"고 공개 발언** — 08-06의 Freund 인정보다 강한 공식 톤. ⑵ **임대+옵션·임대+의무매입 등 대안 구조도 이미 시도됐으나 합의 실패** — 교착이 총액뿐 아니라 구조 협상까지 소진된 상태다. 선수 입장은 변화 없음(잔류가 계획, 측근은 오퍼 청취 지속). 콤파니 중원 서열은 키미히·파블로비치·비쇼프·바라 은디아예. ⚠️ 발행일 함정 회피 1건: givemesport "Villa handed huge boost"(Falk/BILD 경유, 바이에른 호가 인하·임대 수용 가능성)는 **2026-07-21자**라 신선한 진전이 아니다. [2026-08-08 09시 재확인] 홍콩 친선전(08-07, 바이에른 2-1 승) 종료 후 빌라 SD Damian Vidagany가 Sport Bild에 직접 발언: "We are in talks, but there is currently no agreement." 바이에른 요구 €20-25m, 여전히 가격차 교착 — 단계 진전 없음. HIGH 유지. [2026-08-09 09시 재확인 — HIGH 유지] 빌라가 임대+의무매입옵션(단계적 지불) 구조를 대안으로 모색 중이나 바이에른은 완전이적(€25m) 우선 — 구조 교착 그대로. 선수 본인은 "요구액 인하 없으면 잔류도 감수"라는 입장 유지, 뮌헨 잔류 시 연봉 €10m+보너스 €2m 부담이 빌라 PSR에 걸림돌이라는 재정 분석 추가(신규 사실 아님, 정황 보강). 홍콩 대면협상 이후 추가 협상 진전 보도 없음. [2026-08-10 09시 재확인 — HIGH 유지] 단계·구조 전부 불변(빌라=1년 임대 스톱갭 선호 vs 바이에른=완전이적 €25m 고수). Vidagany 공식 발언 "협상 중이나 현재 합의 없음"이 최신 상태 그대로. [경쟁구도 신규] 뉴캐슬이 팔리냐 경쟁에 참전한다는 보도가 등장 — 단계는 관심 수준이고 빌라는 구단 공식 확인 협상 단계라 §2-1상 빌라 우위 유지, 등급 보정 없음. ⚠️[2026-08-10 자기정정] 이 회차의 갱신 내용은 **발행일 확정 실패**다 — Moretto 건은 TransferFeed "1h ago" 스탬프(수집 시각이지 발행 시각이 아님, §1)에만 근거하고 원문 날짜를 잡지 못했다. §2-0에 따라 last_news_date를 08-09로 되돌린다(STALE 시계는 확정된 보도일로만 움직인다). [2026-08-10 21시 — 경쟁 강도 하향 정정] 어제 기록한 "뉴캐슬 참전"의 실체가 드러났다: **뉴캐슬의 1순위는 마르세유의 Højbjerg이고 팔리냐는 그 대안으로 거론된 것**이다. 즉 뉴캐슬은 팔리냐를 주 타깃으로 쫓고 있지 않다 → §2-1 경쟁 강도를 한 단계 낮춰 읽어야 하며 **빌라 우위가 더 명확**해졌다. 단계는 여전히 불변(Vidagany "협상 중, 합의 없음", 가격 €25m·구조 임대vs완전 교착). ⚠️ 신규 서술: 협상이 **08-12 PSG 슈퍼컵 전에 마무리되지 않을 수 있다**는 전망. [2026-08-10 20시 — ⚠️ 이 rationale 첫 문장("€25m 의무구매옵션 가능성 합의, 잉글랜드 이동 중")은 07월 서사이며 현재 상태가 아니다. 후속 대괄호 항목들이 정본이다.] 사용자 제보("임대 이적 마무리 기사")를 §2-0으로 추적한 결과 원출처는 **A Bola 2026-07-17 19:15 「Palhinha a um passo do Aston Villa」**(기사 ID 2026071718151506424가 발행시각 인코딩)이며, 본문은 "토요일 잉글랜드로 이동해 합의를 마무리할 예정"이다. **그 이동도 합의도 일어나지 않았다** — 이미 Plettenberg(Sky DE)가 07-29에 같은 계열 보도(7/19 영국행·합의)를 반박했고 팔리냐는 바이에른 프리시즌에 합류했다. 즉 이 서사는 **24일 된 무산 건**이고, 재검색 시 상위 노출되므로 재순환 위험이 높다. 병기 확인: 같은 A Bola 계열의 벤피카 대안 구조(임대료 €10m + 의무매입 €15m)는 **bolanarede 2026-07-15**자이고 "제출"이 아니라 "제출 예정"이었다 — 이후 벤피카는 지불력 부족으로 탈락했다(07-30 판정). **현 상태 불변**: Vidagany 공식 "협상 중, 합의 없음"(08-07~08), 바이에른 €25m 완전이적 고수, 구조 교착. 오퍼 제출·개인합의·메디컬 보도 전부 0건. **HIGH 유지, last_news_date 갱신 없음**(신규 발행 확정 원문 없음). | [2026-08-12] HIGH 유지. 교착 지점이 **거래 구조**로 특정됐다 — 빌라는 **매입 옵션부 임대**(토트넘 방식) 선호, 바이에른은 **영구 이적** 선호. The Athletic(1티어) 기준 바이에른 호가 **€30m** 유지. [경쟁구도] 뉴캐슬·벤피카 경쟁 중 TEAMtalk 기준 **빌라 선두**. 오퍼·개인합의·메디컬 전부 0건. 공식 사유는 오나나 ACL 시즌 아웃(Vidagany 발언 근거). [2026-08-13] ⭐ **개인 조건은 이미 완전 합의**(Plettenberg/Sky Germany, 2티어) — 어제 "개인합의 0건"으로 적은 것을 정정한다. 막힌 지점은 **거래 구조 하나**로 좁혀졌다: 빌라의 임대+매입옵션 제안을 **바이에른이 거부**하고 영구 이적을 고수한다. 금액 소스 갈림 — Sport BILD €25m vs The Athletic 계열 €30m. Kerry Hau(Sky): 선수 본인이 콤파니 체제에서 전망이 없다고 판단해 오퍼를 구체 검토 중. [경쟁구도] 뉴캐슬·벤피카·스포르팅 대비 **빌라 선두 유지**. 오나나 ACL 시즌아웃이 빌라 측 공식 사유로 계속 인용된다. [2026-08-13 정형값 교정] player_matches의 45분+·hit_points>=15 전체 34경기(2750분)를 core.aggregate로 재집계. RDM 슬롯 제한 argmax는 dm_dlp/Roaming .786. 종전 6경기 값과 산문만 갱신된 불일치를 해소했다.','https://www.transferfeed.com/clubs/aston-villa/15; Record(PT); GiveMeSport; SportsMole ; Plettenberg/Sky DE via onefootball·readastonvilla (2026-07-24, 재검증 07-26); Sports Mole; Yahoo Sports/Bavarian Football Works("on verge"); Jacob Tanswell(Athletic, 팟캐스트); CaughtOffside ; https://www.sport1.de/news/transfermarkt/2026/08/fc-bayern-entscheidet-sich-der-palhinha-poker-in-hongkong (2026-08-06) ; https://bulinews.com/bayern-and-aston-villa-hold-palhinha-talks-after-pre-season-friendly (Sport BILD 경유) ; https://fcbinside.de/2026/08/06/testspiel-wird-zur-transfer-buehne-jetzt-kommt-bewegung-in-den-palhinha-poker/ ; https://www.90min.de/palhinha-poker-vor-neuer-wende-bayern-testet-gegen-interessenten','HIGH 유지 — 임대+콜옵션 구조로 사실상 합의 임박, 톤다운 코멘트 있으나 실행 단계 진입. / [2026-08-03] 경쟁 축 캐비앗: 뉴캐슬은 감독 공백으로 집행력 부재 · 자금은 증가 가능 — 두 방향이 상쇄돼 순효과는 미확정. | [실측 전수 완료 2026-08-12] 2026-08-12 전수 실측(SofaScore 25/26). 종전 6경기 표본을 대체하지 않고 추가한다(불변규칙 2). ⚠️ 표본은 **이전/현 소속 클럽**의 것이고 우리 팀 전술이 아니다(obs#157·#158). tool_x 57.1로 우중앙. RDM(.786) > LDM(.709)이라 **RDM 슬롯이 더 맞는다**. 표본은 바이에른. 45분+ 34경기(2750분) 집계. 종전 6경기 표본 dm_widehalf/Build-Up 0.709 → dm_dlp/Roaming 0.786.');
INSERT INTO transfer_targets VALUES(95,'AVL','2026-summer','João Gomes','주앙 고메스','고메스',56,1015267,'Wolverhampton','DM/CM','LDM','CONFIRMED',NULL,'11111794665X6647968421221',47.0,47.10000000000000142,39,6.769999999999999574,'dm_dlp','Roaming','dm_dlp','Roaming',0.7630000000000000115,unistr('틸레만스 대체 영입 — 클럽간 합의(초기 £34.6m+애드온 £4.3m, 총 ~£38m), 금주 메디컬 예정. 아틀레티코행이 멘데스-구단 갈등으로 결렬된 것을 빌라가 인터셉트. [2026-07-17 실측+3축] 최근 6경기(45분+): 태클 3.7·듀얼 7.0·kp .3·xA .04 — 기능=순수 볼위너+박투박 엔진(카마라형). 움직임 최근접 dlp/Roaming .797(LDM — 우측 배치 .638로 좌측 우세). 기능축 우선(obs#31)으로 처방 dm_holding/Ball-Winning. [2026-07-18 재확인] 메디컬 금요일(7/17) 진행 — 포르투갈 캠프 이탈·귀국 확인, 개인조건 2031년 계약 합의(Schira). 공식 발표 임박. [2026-07-28 FC26 통합 확인] 기능축 우선 처방(dm_holding/Ball-Winning) 유지. 캐비앗: FC26 숙련은 boxcrasher/widehalf/dlp/cm_dlp — holding 마커 없음. 압박검증·슬라이딩태클 PS는 볼위닝 기능 지지. [2026-07-29 홀딩 처방 재검증 — 유지 확정] 현행 커널 재검산: dlp/Roaming .797 정확 재현(stale 아님), holding/Ball-Winning은 .45로 움직임 불일치. 그러나 ①실측 홀딩 동료와 직접 유사 — 온아나 그리드 .835/카마라 .805 (둘 다 움직임 코사인은 dlp .87이었으나 기능축으로 holding 처방된 동일 패턴, obs#32) ②기능=창조 전무(kp .3·xA .04) — dlp 지시는 전개 산출 없는 선수에게 공급 책임 부여하는 모순 ③요구역할=카마라 장기부상 중 앵커 대체+obs#27 블록 전제. 3축 모두 holding 지지 → dm_holding/Ball-Winning 유지. 숙련 캐비앗 대응: holding 미숙련 페널티 확인 시 차선은 dm_boxcrasher/Balanced(.701, 숙련 보유+박투박 기능 부합)이며 dlp가 아님. left-release-A 프리셋의 LDM dlp 공급 요건은 고메스 기능으로 충족 불가 — 진성 DLP형(사라·베르그발) 영입 또는 boxcrasher 절충 필요.\u000a\u000a[2026-07-31 H안] 프리셋 LDM 선발로 승격되며 처방을 dm_holding/Ball-Winning → **dm_dlp/Roaming .789**(숙련✓)로 교체. 커널 교체로 만잠비(.726)와 순위가 역전됐다(이전 만잠비 .812 > 고메스 .797). ⚠️ 캐비앗: 고메스도 기능상 볼위너이고(창조 kp .3·xA .04) 스쿼드에 진성 DLP가 없다 — 적합을 위해 기능 정합을 포기한 칸이다. [2026-08-05 역할 처방 확정 — 기존 dm_dlp/Roaming 유지] LDM(x=38) 전수 채점: dm_dlp/Roaming 0.789 → dm_dlp/Build-Up 0.714(Δ.075) → dm_boxcrasher/Balanced 0.685 → dm_holding/Roaming 0.669(Δ.120) → dm_dlp/Defend 0.578 → … → dm_holding/Ball-Winning 0.452(9/10). RDM에서는 0.680으로 LDM보다 Δ.109 낮아 **좌측 배치 확정**. [기능축 충돌은 계승 — 명시적 지불] 툴 FUNC_AXIS가 고메스를 {role:dm_holding, mode:prefer}로 두고 why에 "창조 전무(kp .3 · xA .04)로 기능축은 볼위너. 다만 dm_dlp 적합이 뚜렷이 높아 프리셋은 dlp를 채택 — 적합을 위해 기능 정합을 포기한 칸"이라 적어뒀다. 2026-08-05 이벤트 측정이 그 근거를 **독립 재현**했다: 키패스 0.30/90(FUNC_AXIS의 kp .3과 정확히 일치). dm_holding/Roaming으로 돌리면 .789→.669로 Δ.120 손실이고 동점 임계(.03)의 4배라 타이브레이커 논리로 정당화되지 않는다 → dm_dlp/Roaming 유지. [카마라와의 3선 분담] 겹침 .715로 가용 피봇 조합 중 최저(고메스↔오나나 .874가 최고 중복, 카마라↔오나나 .814, 카마라↔바클리 .806, 고메스↔바클리 .753). 좌우는 열중심 고메스 46.8 vs 카마라 62.3, 깊이는 수비3rd 고메스 7% vs 카마라 11~15%. **기능 분담은 역할 이름이 아니라 슬롯+선수 능력치가 만든다** — 이벤트 per-90: 고메스 태클 3.52 vs 카마라 2.33 / 카마라 패스 52.5 vs 42.5 · 키패스 0.93 vs 0.30 · 인터셉트 1.40 vs 0.70 · 롱볼 정확도 62.5% vs 44.0%. 즉 카마라 배급·읽기, 고메스 압박·차단. ⚠️ 표본 교란: 카마라는 25-11~26-01 빌라(4위권), 고메스는 26-02~05 울브스 — 약팀 미드필더는 구조적으로 패스가 적고 태클이 많아 교란 방향이 관측과 일치한다. 비율 지표(롱볼 정확도 18.5pp 차·키패스 3.1배)가 더 신뢰된다. ⚠️ 불변규칙 7 — 이 실측은 울브스 체제 표본이므로 개인 위치 성향 기준선으로만 쓰고 에메리 3선 구조의 근거로 쓰지 않는다. 빌라 소속 공식전 표본은 0경기다(프리시즌 5경기는 SofaScore 선수별 데이터 전건 404).'),'SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 39경기.  커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(121,'AVL','2026-summer','Johan Manzambi','만잠비','만잠비',55,1518931,'SC Freiburg → Aston Villa','CM/AM','CAM','CONFIRMED',NULL,'35345X9578542261322300020',46.46999999999999887,61.39000000000000056,12,7.200000000000000177,'cam_halfwinger','Balanced','cam_halfwinger','Balanced',0.8609999999999999876,'합류확정 멀티포지션 부여: 스위스 대표팀 전진 배치 실측 — 월드컵 2경기(캐나다 8.1·알제리 7.8)+친선 2경기(호주·요르단, lineup pos=F) 통합 4경기 168pt, 중심 tool(46.5,61.4). CAM 배치 cam_halfwinger/Balanced 0.817 — 클럽(프라이부르크) 딥롤 그리드의 CAM 적합(0.575)과 달리 대표팀 전진 표본에서 10번 적합 뚜렷. 월드컵 3골(8강 진출)이 이 전진 롤에서 나옴 — 클럽 box-to-box와 별개로 세컨드 스트라이커/10번 활용 여지 실증.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured:national','실측 HIGH — 25/26 전수 12경기. 스위스 대표팀 12경기 통합 — 전진 배치 표본 커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(122,'AVL','2026-summer','Johan Manzambi','만잠비','만잠비',55,1518931,'SC Freiburg → Aston Villa','CM/AM','LM','CONFIRMED',NULL,'35345X9578542261322300020',46.46999999999999887,61.39000000000000056,12,7.200000000000000177,'wm_insidefwd','Balanced','wm_wideplm','Attack',0.6520000000000000239,'합류확정 멀티포지션 부여: LM 순수 출전 표본 없음 — 대표팀 전진 그리드(4경기 168pt)의 LM 슬롯 재배치 적합 0.700(wm_insidefwd/Balanced), 클럽 그리드 기준은 0.607. 좌 하프스페이스 커버는 가능하나 터치라인 고정형이 아닌 중앙 회귀 성향 — 로테이션/변형 옵션 등급.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured:national','실측 HIGH — 25/26 전수 12경기. 스위스 대표팀 12경기 통합 — 전진 배치 표본 커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(123,'AVL','2026-summer','Nicolas Jackson',NULL,'잭슨',76,NULL,'Chelsea','ST','ST','HIGH (정체 — 07-28 이후 단계 전진 없음)','2026-08-09','357324X673345312211100000',45.02000000000000313,67.1700000000000017,28,6.919999999999999929,'st_false9','Attack','st_false9','Attack',0.723999999999999977,'[2026-08-12] 단계 불변(빌라↔첼시↔선수 직접 협상, 합의 0). ⭐ **정체의 원인이 가격 갭만이 아님이 드러났다**: PL은 같은 구단에 한 시즌 **1명 초과 임대를 금지**하는데 빌라·첼시는 **가르나초(출전 연동 의무매입부 임대)로 슬롯을 이미 소진**했다 ⇒ **잭슨은 영구 이적만 가능**하다. 여기에 UEFA 45일 내 상호 이적 = 스왑 처리 규정이 겹쳐 로저스 £117m 매각 이익 계상 타이밍 문제가 붙는다. 호가 갭(£65m/€60m)은 그대로. ⇒ 마감(2026-09-01 23:00 BST) 직전 급진전 시나리오가 유력하다. ⚠️ 원출처는 Florian Plettenberg(2티어, 07-28)이고 08-11 CaughtOffside는 그 재인용(3티어)이라 **단계 변동 근거가 아니다**. [2026-08-13 정형값 교정] player_matches의 45분+·hit_points>=15 전체 28경기(2052분)를 core.aggregate로 재집계. ST 슬롯 제한 argmax는 st_false9/Attack .724. 종전 6경기 정형값을 전수 실측값으로 교체했다.','Fabrizio Romano(1티어) 관심·에메리 각별 신뢰 확인 ; Football Insider(2티어) £60-65m 요구 ; Yahoo Sports "step up talks" ; SofaScore API player 1085381 (2026-07-21) ; thehardtackle(2026-07-19,21) 논의/가격 설정 ; Yahoo Sports(잭슨 open to move) ; teamtalk(2클럽 논의 중) ; Romano X 2079473534951211218 ; teamtalk nicolas-jackson-villa-break-transfer-record (재검증 07-26); Sky Sports; BBC(gossip); TeamTalk; Africasoccer ; [08-05 심층] Ornstein/The Athletic(1티어) 2026-07-22 4년 계약 골격 via https://uk.sports.yahoo.com/news/why-aston-villa-sign-nicolas-180000917.html ; Plettenberg/Sky Germany 2026-07-28 https://www.caughtoffside.com/2026/07/28/aston-villa-nicolas-jackson-transfer-florian-plettenberg/ ; Romano 2026-07-28 임대 불가 확정 https://www.givemesport.com/aston-villa-nicolas-jackson-chelsea-transfer-romano-update/ ; Sky Sports(Sheth) 회의론 영상 2026-07-28 https://www.skysports.com/football/video/12606/13567768/nicolas-jackson-why-aston-villa-may-avoid-signing-striker-from-chelsea ; 웰벡 첼시 이적 2026-08-01 https://www.espn.com/soccer/story/_/id/49478554/danny-welbeck-chelsea-brighton-premier-league-transfers ; BBC 알론소 발언 2026-08-04 ; Daily Mail(Rosser) 2026-08-04 스퍼스 참전 → 당일 football.london 부정 https://www.sportsmole.co.uk/football/spurs/transfer-talk/news/nico-or-nic-no-jackson-to-tottenham-transfer-truth-revealed_602396.html','HIGH 유지 — 1티어(Sky) 협상 진행 확인, 기록적 이적료 임박 분위기. [2026-08-03 21시] 임대 경로 봉쇄는 규정 근거(PL 동일구단 임대 1명)라 보도 티어와 무관하게 성립 — 단, 가르나초 딜이 임대 구조라는 전제에 의존한다(현재 조건부 임대+£40m 완전이적 옵션으로 보도됨). [2026-08-05 심층 추가] ⓐ ⚠️ 실측 출처 미확정(검증 백로그) — source의 "SofaScore API player 1085381 (2026-07-21)" 6경기 표본이 어느 대회 것인지 DB에 기록돼 있지 않다. 잭슨은 25/26 시즌 전체를 바이에른 뮌헨 임대로 보냈고(2025-09-01~2026-06-30) 2026 월드컵에 세네갈 대표로 출전했다. 따라서 2026-07-21 기준 "최근 6경기"는 바이에른 25/26 경기·월드컵 경기·혼재 중 어느 것도 가능하다. club 필드의 "Chelsea"는 소속 구단이지 측정 출처가 아니다. 월드컵 표본이 섞였다면 클럽 전술 맥락과 다른 데이터이므로 재수집이 필요하다. → 다음 SofaScore 접근 시 event id 목록을 확인해 rationale에 명기할 것. ⓑ 선수 의사 상충 — TEAMtalk(Graeme Bailey) 07-24 "에메리 재회에 매우 열려 있고 완전이적을 원한다" vs The Sun 07월 "첼시에 남아 알론소 밑에서 증명하기로 결심" vs Daily Mail(Jack Rosser) 08-04 "보장된 출전시간을 찾아 떠날 준비". 본인 직접 발언 원문은 이번 창에 확보되지 않았다(DSPORTS "나는 첼시 선수다"는 2025년 창 발언). 공통분모는 "출전시간 보장 요구"이며, 바이에른에서 전 대회 선발 15경기에 그친 경험이 결정 변수다 — 빌라가 왓킨스 위 서열을 보장하지 못하면 본인 동의가 흔들릴 수 있다. ⓒ 알론소 08-04 홍콩 기자회견(BBC, 1티어)은 중립~잔류 톤 — "니코는 훌륭한 선수", "함께 있어 기쁘다", "하루하루 옵션을 점검하겠다", "시장은 아직 3주 남았다". 매각 확정 뉘앙스가 아니다. 알론소는 전통적으로 장신 타깃형 9번을 선호해 조앙 페드로·에메가가 그 틀에 더 맞는다는 분석이 병기된다. ⓓ 계약이 2033년까지라 레버리지는 전적으로 첼시에 있다 — 급히 팔 이유가 없다는 점이 £65m 고정 호가를 지탱한다. ⓔ 부상 이력(Transfermarkt): 25/26 무부상, 24/25 햄스트링 58일(10경기), 23/24 발목 56일, 22/23 고관절 57일(15경기), 20/21 근섬유 파열. 누적 결장은 적으나 "한 시즌 1회 8주급" 근육·관절 패턴이 반복된다. 2026 월드컵 + 2025 AFCON 참가로 여름 부하 누적이 리스크. ⓕ ⚠️ §2-0 휴리스틱 실패 사례 기록 — 이 건에서는 "나이 표기로 재순환 기사를 거른다"는 규칙이 오탐을 낸다. 2026년 창에 실제 발행된 기사들이 잭슨 나이를 제각각 틀리게 적었다(TEAMtalk 07-24 "25" 정확 / GiveMeSport 07-24 "23" / Yahoo 07-20 "27" / Yahoo 08-04 "24"). 마지막 건은 "24세"로 쓰면서 본문에서 08-05 홍콩 유벤투스 친선전을 언급해 명백히 2026-08 발행이다. → 이 선수에 한해 대체 판별 지표를 쓸 것: 로저스 첼시 £117m · 가르나초 빌라 임대 · 만잠비 빌라 £59.5m(07-17) · 웰벡 첼시 이적(08-01) · 알론소가 현 감독이고 마레스카는 전 감독 · 첼시 25/26 리그 10위 유럽대항전 없음 · 맨유 감독 Michael Carrick · 바이에른이 매수옵션 포기(2025년 기사는 "관심 중" 단계). ⓖ 인용 금지: newsstation2.com 2026-08-01 "빌라-첼시 합의·메디컬 예정"은 콘텐츠 팜이며 1·2티어 교차확인 0건, 08-04 Daily Mail·BBC가 여전히 미해결로 서술해 사실상 반증됐다. BBC 가십 07-29 "첼시가 로저스 대가로 Tosin+잭슨+현금 제안"은 로저스 딜이 07-20경 이미 합의된 것과 시간순 모순이라 근거로 쓰지 말 것. | [실측 전수 완료 2026-08-12] 2026-08-12 전수 실측(SofaScore 25/26). 종전 6경기 표본을 대체하지 않고 추가한다(불변규칙 2). ⚠️ 표본은 **이전/현 소속 클럽**의 것이고 우리 팀 전술이 아니다(obs#157·#158). tool_x 45.0으로 약간 좌측 드리프트(좌2 0.45). 표본은 첼시. 45분+ 28경기(2052분) 집계. 종전 6경기 표본 st_advanced/Support 0.752 → st_false9/Attack 0.724.');
INSERT INTO transfer_targets VALUES(129,'AVL','2026-summer','Alejandro Garnacho',NULL,'가르나초',58,NULL,'Chelsea','LW','LM','CONFIRMED',NULL,'77111X4111510006100010100',22.30000000000000071,66.5,38,6.990000000000000213,'wm_winger','Attack','wm_winger','Attack',0.7710000000000000186,unistr('첼시 초기 로그론 + 의무구매옵션(사실상 확정), 4년 계약. Romano "here we go" + Ornstein 메디컬 완료 확인 (2026-07-22/23). [2026-07-28 FC26 통합 확인] 실측 0.911 + 숙련 wm_insidefwd+ 일치 + PAC86/감아차기 — 처방 확정.\u000a\u000a[2026-07-31 obs#94 커널 교체 + H안 재설계] 처방을 wm_insidefwd/Attack → **wm_winger/Attack .804**(숙련✓)로 교체. 옛 placedMap이 인사이드 포워드 커널을 터치라인(x=14)으로 시프트해 적합을 .911로 부풀리고 있었고, EA 정본 변형으로는 .671이다. 실측에 맞는 것은 winger 계열이며 좌측 해방의 성격이 컷인 → 터치라인 침투로 바뀐다. 뱅크는 0.00 유지라 C1(두 줄 4) 무사.'),'SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 38경기.  커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(135,'AVL','2026-summer','Emerson Royal','에메르송 호이알','에메르송',NULL,856123,'Flamengo','RB','RB','DEAD (STALE — 최신 보도 2026-07-28 이후 2주+ 무소식)','2026-07-28','000250002X000150002600012',86.20000000000000284,56.70000000000000284,6,6.879999999999999894,'fb_att_wb','Support','fb_att_wb','Support',0.949999999999999956,'Matty Cash 백업 필요(안드레스 가르시아 게타페 임대行) — Villa가 Flamengo에 €9m 공식 제안 제출(6/23), Flamengo 거부 후에도 재제안 검토 중. Sky Sports Paper Talk(출처: The Athletic)가 협상 사실 보도, 선수 본인도 공개적으로 제안 수령 확인. 아직 합의 단계 아님(Flamengo 계약 2028까지, 판매 거부 기조) → MEDIUM-HIGH(1티어 협상 보도, 합의 전). [2026-07-29 14시 재확인 — 유지] 디테일 진전: 블록 주체=자르딤 감독(ESPN Brazil Andrade — "회장단은 승인 의향, 감독이 중단"). €9m→€10m 증액 제안도 보류됨. 선수는 공개적으로 긍정 반응, 협상 재개 여지 유효. [2026-07-30 실측 완료] 툴중심(86.2,56.7)=우측 전용. RB 커널 적합 fb_att_wb/Support 0.950 > fb_inverted/Attack 0.923 — 캐시 실측의 동일역할 적합(0.898)을 상회. 전방2행/자기진영2행 질량비 0.53/0.31 vs 캐시 0.33/0.47 → 캐시보다 뚜렷한 전진형 풀백(공격 관여 +0.20, 수비 커버 -0.16). 함의: C(우측 침투) 프리셋의 RB 처방 fb_att_wb/Support에 캐시보다 정합적이나, 자기진영 질량 하락이 이미 라인 48로 내린 C의 수비 리스크를 더한다 — 프리셋 채택은 별도 판단. [경쟁구도 2026-07-30] 빌라 단독 우위(경쟁 클럽 0건) — 오퍼를 낸 유일한 클럽이고 선수도 공개 호응("이 제안을 받아 매우 기쁘다"). 장애물은 경쟁이 아니라 플라멩구의 스쿼드 판단: Casagrande(플라멩구 전담) — 지금 팔면 자르딤이 바렐라의 즉시 대체자를 잃는다는 이유이며 금전 문제가 아니다(빌라는 이미 호가 충족, 결렬이 아니라 냉각). 상향 트리거 = 플라멩구의 우측 백업 확보(에스투피냔-밀란 블록과 동일 패턴). [2026-08-09 재확인 — MEDIUM-HIGH 유지, 신규 근거 0건] 오늘 검색에서도 최신 보도가 6월말~7월 수준(플라멩구가 스쿼드 뎁스 우려로 €10m 오퍼 거부, 매각 자체를 보류)에 머물러 있다. 선수 본인은 "제안을 받아 기쁘다, 미래는 모른다"로 문을 열어둔 상태 유지. ⚠️ **last_news_date 2026-07-28 기준 STALE 시한(14일)은 2026-08-11** — 08-09 현재 12일 경과, 2일 남았다. 다음 회차(21시)~08-11에 신규 보도가 없으면 §4-3에 따라 DEAD(STALE) 전환 대상이다. 재확인 날짜를 last_news_date로 쓰지 않는다(§4-3 함정 규칙). [2026-08-10 심야 — STALE 전환 근거 확정] 전용 검색 2회로 **08-01 이후 빌라 링크 신규 보도가 0건**임을 확인했다(오늘 검색에 걸린 전건이 6월말~7월 빈티지의 재순환). 확인된 최신 실보도 타임라인: 2026-06-23 €9m 오퍼(ESPN Brasil) → €10m 인상(Venê Casagrande) → **플라멩구가 RB 뎁스 우려로 매각 철회**(재정 사유 아님 명시 — Varela와의 경쟁 필요) → 7월말 Bruno Lemos "빌라는 플라멩구의 대체자 확보를 기다리는 중". 선수 본인 발언(Itatiaia Esporte)도 7월 것이다. 계약 2028 + 1년 옵션. ⇒ `last_news_date` 2026-07-28 기준 오늘 **13일**. **08-11 시한 도달 시 §4-3 전환 근거가 성립한다**(신규 근거 0건 확인 완료). ⛔[2026-08-10 STALE 전환 집행] §4-3에 따라 `DEAD (STALE)`로 전환한다. **실질 근거**: 스캔 에이전트가 전용 검색 2회로 **08-01 이후 빌라 링크 신규 보도 0건**을 확인했고(검색에 걸린 전건이 6월말~7월 빈티지의 재순환), 최신 실보도는 7월말 Bruno Lemos "빌라는 플라멩구의 대체자 확보를 기다리는 중"에서 멈춰 있다. ⚠️ **절차 명기**: 전환일 기준 경과는 **13일**로 §4-3의 "14일 초과"에 하루 못 미치며(14일 시점 = 2026-08-11), **사용자 판단으로 하루 앞당겨 집행**했다. 실질 요건(신규 근거 0건)은 충족돼 있다. ⚠️ **삭제하지 않는다** — 이 행은 `fit_sim` **0.95**(현 후보 최고값)와 `map25` 실측을 보유하며, §4-3이 정체 건을 지우지 않는 이유가 정확히 그 상실 방지다. DEAD만으로 `injectTransferCandidates()`가 `/^DEAD/i`를 필터해 툴·SQUAD_SLOTS·XI_POOL에서 사라진다. **복원 조건**: 빌라 링크 신규 보도 확인 시 §2 등급표로 재판정해 `likelihood` 되돌리고 `last_news_date` 갱신, `rationale`에 `[STALE 해제 YYYY-MM-DD]` 기록.','Sky Sports(via The Athletic) 2026-07; Yahoo Sports/Sports Mole 2026-07','실측 6경기(45분+·히트포인트 62~107): FLA-SPA 90''7.1 / CHA-FLA 90''6.7 / FLA-COR 90''7.1 / FLA-CUS 90''7.1(리베르타도레스) / FLA-ELP 90''6.7(리베르타도레스) / VIT-FLA 90''6.6(코파) — 2026-05-15~07-26, 평균 6.88. 캐비앗: ① 브라질 리그·남미 대회 표본(리그 강도 보정 없음, 시세 LASK 사례와 동일 한계) ② 프리시즌 친선 4경기는 표본 제외 ③ INT-FLA(26'')·CAP-FLA(8'')·GRE-FLA(25'')은 45분 미달로 제외. 측정: claude-in-chrome, SofaScore API event/{eid}/player/{pid}/heatmap.');
INSERT INTO transfer_targets VALUES(139,'AVL','2026-summer','Allan','아우안','아우안',77,1835889,'Palmeiras','RW/CAM','RM','MEDIUM-HIGH','2026-08-09','012350125X111370012700013',77.14000000000000056,56.8299999999999983,42,7.089999999999999858,'wm_winger','Balanced','wm_winger','Balanced',0.8139999999999999458,'로저스(첼시 £117m) 대체 창조 자원. 빌라가 €25m+옵션 €5m(총 €30m)·5년(+1년 옵션) 공식 입찰 → 팔메이라스 거절. SD Anderson Barros가 대리인에게 "협상 의사 없음" 직접 통보, 요구선 €45m 초과(나폴리 €35m·뉴캐슬·제니트 기거절). 계약 2029로 셀링클럽이 협상력 우위. [경쟁구도 2026-08-01] 단계는 빌라가 최선두(유일한 실제 입찰) — 뉴캐슬·리버풀은 관심 단계 보도뿐. 판정 **빌라 우위**이나 병목은 경쟁 클럽이 아니라 **셀링클럽 블록**이다. 등급 유지(HIGH는 협상 단계 요건 미충족 — 상대가 협상 자체를 거부). [실측 2026-08-01] SofaScore 히트맵 6경기(45분+·히트포인트 15+, 2026-05-05~07-30, 전부 팔메이라스) 균등가중 그리드. 중심 툴좌표 (77.2, 59.4) = **우측·전진** 편향이 뚜렷하고 평균 평점 **7.18**(최고 8.4). RM 슬롯(x=85) 커널 적합 **wm_winger/Balanced .812** — 기존 RM 후보 하지무사 .821·은디아예 .825와 **동급**이고 둘 다 DEAD인 지금 RM 슬롯의 유일한 실측 보유 후보다. ⚠️ W군(순수 윙어)으로 재면 w_wideplm/Build-Up .870으로 더 높다 = **뱅크(WM) 역할보다 해방 윙어에 가까운 풋프린트**이며, 에메리 우측이 요구하는 4-4-2 복귀(obs#27)와는 그만큼 어긋난다. CAM으로 재면 .674로 급락 → 등재 슬롯은 RM이 맞다. [2026-08-01 처방] opt=fit=wm_winger/Balanced(.812) — 타 영입 후보와 같은 규약(실측 argmax를 처방으로). ⚠️ 현 구조에서 RM은 두 줄 4의 **뱅크 칸**이라(obs#124) 실제 기용 시 wm_widemid/Support **.734**를 지불하게 된다(−.078). 즉 아우안은 해방 사이드용 자원이고, 좌측이 이미 해방으로 우세한 현 스쿼드에서는 구조적으로 어긋난다. [2026-08-02] ESPN Brasil(Bruno Andrade): 빌라는 **포기하지 않았고 2차 입찰을 준비 중**이다 — 다만 **아직 제출 전**이라 단계 변화는 없다(등급 유지). 팔메이라스가 협상 자체를 거부 중이라 이번 창 내 성사는 회의적이고, 브라질 시즌 종료 후 1월 재평가가 현실적이라는 관측이 병기된다. [2026-08-03] 셀링클럽 구조 제약 확인 — 팔메이라스는 Allan 경제권 70%를 보유하고 **국외 이적 바이아웃 €100m(R$630m)** 이 걸려 있다. ⚠️ 이 조항은 빌라 관심에 대한 신설 대응이 아니라 **2024-11 재계약 때부터 존재하던 상수**다(ESPN Brasil, 최초 보도 2025-02-25 — 당시 2027 만료·€100m, 이후 2029로 연장). 즉 €45m+ 요구선과 €100m 조항은 별개 층이며, 협상 결렬 시 빌라가 넘어야 할 실제 천장은 후자다. 추가로 아벨 페레이라가 기자회견에서 "협상이 이뤄진다면 주변부 선수에 한한다"고 직접 발언(1차 출처=공개 회견). ⚠️ **2030까지 재연장+조항 증액 협상 중**이라는 서술은 thefootball.com.br(3티어, 기자 미표기) 단독이라 채택하지 않는다 — ESPN 기사에는 해당 내용이 없다. [2026-08-09 최신화 — MEDIUM-HIGH 유지, 셀링클럽 블록 확인] ⚠️ 소속팀은 팔메이라스다(플라멩구 아님 — 플라멩구의 Allan은 동명이인 Allan Rodrigues, 현재 코린치안스 임대). ESPN(sources 기반): **빌라의 €30m 오퍼를 팔메이라스가 거부**했고 €45m 수준으로의 인상을 요구. 오퍼 구조는 고정 €25m + 보너스 €5m + 5년 계약(+1년 옵션). TeamTalk: 팔메이라스 회장 Leila Pereira와 감독 Abel Ferreira가 매각에 반대하며 "최근 아카데미 최고 재능, 가치가 계속 오를 선수"로 판단 — 빌라의 오퍼에 감사를 표하되 **비매품 통보**. [등급 판단] §2-1 보정표상 이는 "경쟁 클럽 우위"가 아니라 **셀링클럽 기조(잔류·호가)** 사유다. 빌라는 관심이 아니라 **실제 공식 오퍼를 제출한 단계**이고 2차 입찰도 배제되지 않았으므로 MEDIUM-HIGH 유지 — 다만 €15m 갭과 구단 수뇌부의 공개 반대가 병목이다. 선수: 22세, 2026시즌 6골 4도움, 통산 88경기 16공격P. 리버풀·뉴캐슬도 링크. [2026-08-13 정형값 교정] player_matches의 45분+·hit_points>=15 전체 42경기(3166분)를 core.aggregate로 재집계. RM(WM군) 슬롯 제한 argmax는 wm_winger/Balanced .814. 순수 W군 .837은 EA 노이즈 구간 차이(.023)의 참고값이며 실행 슬롯 정형값에는 쓰지 않는다.','ESPN(1티어, Adriana Garcia 기명, sources 표기, 2026-07-29) https://www.espn.com/soccer/story/_/id/49478318/aston-villa-premier-leauge-allan-brazilian-serie-30-million-offer-rejected-sources ; 최초 정보 André Hernan(BR) ; TEAMtalk','MEDIUM-HIGH — 1티어가 **실제 제출된 입찰**을 확인(단순 관심 아님). 실측 완료(2026-08-01) — 6경기 균등가중, 인코딩 규약은 맥긴 14023928 회귀 검증(44포인트·25셀 완전 일치)으로 확인. ⚠️ 표본이 전부 **브라질 세리에A**라 리그 수준 보정 없음. ⚠️ 적합 .812는 슬롯 유형 WM 제한 하의 argmax이고, 무제한이면 W군이 더 높다(위 캐비앗). [2026-08-03] €100m 바이아웃은 ESPN Brasil로 교차 확인됨(신설 아님·상수). 2030 재연장설은 미채택(3티어 단독). | [실측 전수 완료 2026-08-12] 2026-08-12 전수 실측(SofaScore 25/26). 종전 6경기 표본을 대체하지 않고 추가한다(불변규칙 2). ⚠️ 표본은 **이전/현 소속 클럽**의 것이고 우리 팀 전술이 아니다(obs#157·#158). **41/43 우측 우세**. RW(.837) > RM(.814)이나 Δ.023은 EA 노이즈 구간이라 슬롯은 RM 유지. 표본은 팔메이라스(브라질 세리에A) — **리그 수준 보정 없음**. 45분+ 42경기(3166분) 집계. 종전 6경기 표본 wm_winger/Balanced 0.812 → w_winger/Balanced 0.837.');
INSERT INTO transfer_targets VALUES(141,'AVL','2026-summer','Matteo Ruggeri','마테오 루헤리','루헤리',NULL,965011,'Atlético Madrid','LB','LB','HIGH','2026-08-12','32100X2000410007200031000',13.59999999999999965,47.20000000000000284,6,6.769999999999999574,'fb_att_wb','Support','fb_att_wb','Support',0.948999999999999955,'[2026-08-11 갱신] Romano(1티어, 08-11 22:41): **개인 조건 합의 완료**, 선수가 버밍엄으로 이동해 **메디컬·계약 서명 진행 가능**. 이적료는 종전 €20m 표기에서 **€25m + 애드온 €1.5m(총 €26.5m)** 로 정정. [경쟁구도] 리버풀·뉴캐슬 관심은 소멸, 빌라 단독 우위. 아틀레티코는 그리말도 영입 후 매각 의사. ⚠️ **CONFIRMED 아님** — 메디컬 완료·구단 공식 발표 0건이고 Romano의 ''here we go''도 아직 없다. 슈퍼컵(08-12) 전 등록은 무산됐다. 다음 회차 CONFIRMED 전환 1순위. [2026-08-13] **메디컬 단계 진입** — Romano(1티어) 08-12 트윗 `2087469710958850427`: "오늘 늦게 잉글랜드로 이동해 빌라 메디컬". 08-11 "here we go" 후속이다. 08-13 현재 **구단 공식 발표 0건**이라 CONFIRMED 전환은 보류 — 다음 회차 1순위 그대로. 이적료 €25m + €1.5m 애드온(총 €26.5m) 불변.','Marca(스페인 전국지, 원출처) via Matteo Moretto(준1티어) ; https://www.sportsmole.co.uk/football/aston-villa/transfer-talk/news/emery-wants-to-sign-italian-defender-immediately-as-aston-villa-bid-to-resolve-clear-issue_602381.html ; http://insidefutbol.com/2026/08/04/aston-villa-push-for-defender-as-he-weighs-his-options/722198/ ; https://www.eurosport.es/futbol/mercado-de-fichajes-2026/2026/aston-villa-interes-matteo-ruggeri-atletico-de-madrid_sto23325237/story.shtml ; https://uk.sports.yahoo.com/news/aston-villa-could-seal-immediate-101500950.html ; SofaScore /api/v1/player/965011/events/last/0 + /event/{eid}/player/965011/heatmap|statistics ; The Athletic(Jacob Tanswell, 1티어, 2026-08-04, paywall 미열람 — 인용 3매체 발행시각 일치로 확정) ; Marca(Isaac Suarez) 2026-08-04 via Sport Witness ; https://www.givemesport.com/aston-villa-identify-mattero-ruggeri-digne-replacement-transfer/ (2026-08-04) ; Tinti 발언 https://www.romaforever.it/2026/07/21/ruggeri-si-allontana-lagente-tinti-fa-chiarezza-sul-suo-futuro/ (2026-07-21) ; Total Football Analysis 스카우트리포트 2025-07-24(⚠️아탈란타 24/25 데이터) | https://www.marca.com (2026-08-05, via readastonvilla.com/2026/08/05/aston-villa-agree-20m-matteo-ruggeri-deal-as-final-hurdle-remains/) | https://insidefutbol.com/2026/08/05/aston-villa-move-blocked-for-now-as-definitive-yes-is-missing/ (Moretto) ; Romano via football-italia.net/done-ruggeri-agrees-personal-terms-aston-villa/ (2026-08-11)','MEDIUM-HIGH — 2티어(Marca, 원출처 직접 보도) + 준1티어(Moretto)가 오퍼 제출 단계를 보도. 1티어(Romano/Sky/BBC/Athletic) 직접 확인은 검색에서 미발견이라 HIGH 미충족. §2-0 발행일 검증 통과: 발행일 2026-08-04 확정, 나이 표기 24세가 실제(2002-07-11생 → 24세)와 일치, 병기 정황(그리말도 아틀레티코 입단·그리스만 올랜도 자유이적·랑글레 벤피카 임대·디뉴 PSG)도 현재 상태와 부합 → 1년 오차 함정 아님. 캐비앗: ⑴ 선수 결정 대기 상태로 무산 가능성 상존, ⑵ 2주 전 대리인 Tinti의 ''아틀레티코 잔류가 계획'' 발언(Sky Sport Italia)과 상충 — 오늘 보도가 더 최신이라 채택하되 상충 사실 명기, ⑶ 실측 표본이 25/26 시즌 종료분이라 아틀레티코 1년차 역할 기준(그리말도 영입 전). [2026-08-05 심층 추가 캐비앗] ⑷ 이적료 보도 충돌 — Cerchione €18m+€3m(최대 €21m, 구조 제시) vs The Athletic ~€25m(총액, 티어 우위). 어느 쪽도 다른 1티어가 복제하지 않았다. ⑸ 선수 측 의사 충돌 — 대리인 Tinti의 2026-07-21 Sky Sport Italia 발언 "아틀레티코에 남는다, 시장에 나와 있지 않다"가 08-03~04 훈련 제외·대리인 마드리드 방문과 정면 충돌. 협상 포지셔닝이었을 가능성이 높으나 선수 본인의 이탈리아 복귀 선호의 흔적일 가능성도 배제 못 함 — 확정 근거 없음. ⑹ 인용 함정 2건 명기: (a) Total Football Analysis 스카우트 리포트는 제목이 "Atletico Madrid 2025/2026"이나 실제 발행 2025-07-24·데이터는 아탈란타 24/25 기반이다 — 25/26 아틀레티코 평가로 인용 금지. (b) BirminghamWorld "Fabrizio Romano confirms £17m deal"은 2025-06 아탈란타→아틀레티코 이적 건으로, 빌라 딜의 1티어 근거로 오인하기 쉬운 재순환 기사다. ⑺ 08-04 기록의 발행일 교차검증 항목 중 "그리스만 올랜도 자유이적"은 2026-08-05 재확인에서 검증 실패(그리즈만은 여전히 아틀레티코 스쿼드에 포함) — 나머지 3개 병기 정황(그리말도 입단·랑글레 벤피카·디뉴 PSG)은 유효하므로 발행일 판정 자체는 유지하되 이 항목은 근거에서 제외한다. ⑻ 실측 한계: @dom/@tight 및 국면(possH/possL) 분리 표본이 없어 에메리의 "풀백은 한 명씩만 전진" 모듈레이션 수행 가능 여부는 판정 불가(디뉴·마첸은 해당 행 보유). ⑼ 부상 이력 — 2021-09~2023-04 근육 부상 클러스터(최장 4개월) 이후 2024년부터 안정화, 25/26 아틀레티코 시즌 부상 기록 없음. 내구성 리스크 LOW-MEDIUM. ⑽ 신체·산출 맥락: 187cm 왼발, 공중볼 승률 92.1퍼센타일(24/25 5대리그 LWB 대비) — The Athletic이 말한 "physical profile"의 정량 근거. 25/26 라리가 26경기(20선발) 1,775분 0골 3도움, 크로스 95회(4.8회/90), 태클 1.88·인터셉트 1.01·클리어 3.19/90. 세리에A 30경기 3도움 → 라리가 26경기 3도움으로 3백 윙백→4백 풀백 전환에도 분당 생산성 유지. | 2026-08-06: 합의 보도는 2티어 복수(Marca·Uria·Moretto) 일치, 1티어 직접 확인은 The Athletic 관심 보도까지. Romano "here we go" 미발행 — CONFIRMED 아님. Mundo Deportivo 원문 발행일 미확정이라 last_news_date는 확인된 08-05로 기록. | [실측 전수 완료 2026-08-12] 2026-08-12 전수 실측(SofaScore 25/26). 종전 6경기 표본을 대체하지 않고 추가한다(불변규칙 2). ⚠️ 표본은 **이전/현 소속 클럽**의 것이고 우리 팀 전술이 아니다(obs#157·#158). **45/45 전 경기 좌측 우세**(좌2컬럼 0.98·우2 0.00)라 좌우 혼입 없음. 표본은 아틀레티코 마드리드. 45분+ 45경기(3612분) 집계. 종전 6경기 표본 fb_att_wb/Support 0.949 → fb_att_wb/Support 0.931.');
INSERT INTO transfer_targets VALUES(142,'AVL','2026-summer','Endrick','엔드릭','엔드릭',NULL,NULL,'Real Madrid','RW/ST','RM','DEAD (레알 잔류 결정 — 2026-08-10 Romano/The Athletic)','2026-08-10','013440137X001350112200000',NULL,NULL,20,7.0,'wm_wideplm','Attack','wm_wideplm','Attack',0.8469999999999999752,'[2026-08-12 정정] **08-11 MEDIUM-HIGH 등재는 오류였다.** 근거로 삼은 Romano 발언("관심 있는 두 클럽 — 로마와 아스톤 빌라")보다 **같은 날 나온 더 늦은 Romano 보도**가 결론이었다: 레알이 엔드릭과 그의 에이전트(Roc Nation 포함)에게 **잔류 결정을 통보**했고 무리뉴가 임대 협상을 전면 중단시켰으며 페레스도 동의했다(The Athletic Mario Cortegana 08-10 병행 보도). ⭐ **1월에 재논의하기로 한 것이 확인된다** — 겨울 창 재개 가능 건이므로 완전 종결이 아니다. [경쟁구도] 로마·맨유도 함께 무산. 실측(obs#135, 리옹 임대 20경기 우2컬럼 77.1%)과 커널 적합(RW .907 / RM wm_wideplm/Attack .847)은 보존한다 — 겨울 재개 시 재측정 불필요.','Fabrizio Romano 발언(2026-08-10) via football365 https://www.football365.com/news/aston-villa-real-madrid-endrick-fabrizio-romano-transfer-update ; AS 원보도 via Managing Madrid https://www.managingmadrid.com/111142/endrick-real-madrid-loan-deal-2026-news ; Fotmob rumours teamIds=10252 (RW Endrick / 어제 / AS) ; 실측 obs#135 SofaScore pid 1174937 ; [정정 근거] Romano 잔류 통보 보도 + The Athletic Mario Cortegana (2026-08-10) via https://www.si.com/soccer/real-madrid-u-turn-endrick-2026-27-season','DEAD — 무산 확정(레알 잔류 결정 통보). ⭐⭐ **이 건은 §2-0 지표 4의 실패 사례로 남긴다**: "같은 매체 안에서도 최신순 정렬을 하라 — 연도가 맞아도 이미 뒤집힌 중간 기사일 수 있다"가 **같은 날 안에서도 성립**한다. 08-11 등재 시 Romano 발언을 인용한 football365 기사를 잡았는데, 동일 08-10에 Romano가 잔류 결정을 별도로 보도했고 그쪽이 결론이었다. 발행일(08-10)이 맞았기 때문에 지표 1~3으로는 잡히지 않았다 — **날짜가 같아도 시각 순서를 봐야 한다.** ⚠️ 행을 삭제하지 않는다(§4-3 논리) — map25·fit_sim·실측 표본을 보존해야 2027-01 재개 시 재측정이 불필요하다. 툴은 /^DEAD/i를 필터하므로 후보 목록에서는 사라진다.');
INSERT INTO transfer_targets VALUES(143,'CHE','2026-summer','Pep Chavarría','차바리아','차바리아',80,NULL,'Rayo Vallecano','LB','LB','CONFIRMED','2026-08-12','510009210093100X510053100',NULL,NULL,39,6.799999999999999823,'fb_att_wb','Support','fb_att_wb','Support',0.8900000000000000133,'[2026-08-12 상향] Romano **"here we go"**(1티어, 원트윗 status 2085475147692061073, **2026-08-06 22:16**) — 첼시가 라요 바예카노와 합의, **€19m 고정 + €2m 애드온**. 후속 트윗(2085617184093446637, 08-07)에서 **메디컬·계약 서명을 위해 잉글랜드 이동**. Sky 수석기자 Kaveh Solhekol(1티어, 08-05)도 £16.3m+애드온으로 병행 보도. ⚠️ **어제 기록한 €25m은 Fotmob 추정치였다 — 실제는 €19m+€2m**. [전술 근거] Sky·The Athletic 공통 서술: **공을 앞으로 몰고 나가는 유형**의 좌측백이라 ''풀백이 볼을 전진시키라''는 알론소 지시에 부합. 포지션은 **하토의 백업·경쟁**이며 하토가 개막 주전 유력 — 주전 결손 메우기가 아니라 로테이션 보강이다. 쿠쿠렐라(→레알 £51.7m) 이탈의 대체. [경쟁구도] 경쟁 클럽 보도 0건, 첼시 단독. [2026-08-13 CONFIRMED] **첼시 구단 공식 발표 확인** — chelseafc.com 전용 발표 기사, **2031년까지 계약**. 어제 달아둔 "구단 공식 미확인" 캐비앗 해소. 이적료 €19m 고정 + €2m 애드온이 공식 보도로 재확인됐다(Romano 수치와 일치). 하토 백업·경쟁 구도 유지.','Fabrizio Romano 원트윗 status 2085475147692061073 (2026-08-06 22:16, "here we go") + status 2085617184093446637 (08-07 메디컬) ; Sky Sports Kaveh Solhekol (2026-08-05) ; The Athletic (08-05) ; 리드 Fotmob teamIds=8455 ; https://www.chelseafc.com/en/news/article/pep-chavarria-signs-for-chelsea (구단 공식)','HIGH — 1티어 3개 독립 확인(Romano 원트윗 2건 + Sky 수석기자). §2-0 발행일 검증 통과: 본문 나이 **28세**가 실제와 일치하고 병기 상황(쿠쿠렐라 레알행, 하토가 유일 좌측백, 알론소 부임)이 전부 26/27 창과 정합. 트윗 status ID로 발행 시각까지 확정했다. ⚠️ **CONFIRMED 아님** — 첼시 구단 공식 발표를 오늘까지 확인하지 못했다(08-11 시점 ''발표 임박''). 다음 회차 CONFIRMED 전환 1순위. ⚠️ 실측 PENDING — SofaScore 55경기 수집은 완료했으나 슬롯 판정·집계는 미수행. | [실측 완료 2026-08-12] SofaScore 25/26 전수 55경기 중 45분+ 39경기 집계. **39/39 전 경기 좌측 우세**(좌2컬럼 0.93·우2 0.00)라 좌우 혼입 없음 — 만잠비형 함정(obs#156) 해당 없음. ⚠️ 표본은 **라요 바예카노** 소속이고 첼시·알론소 체제가 아니다(obs#157).');
INSERT INTO transfer_targets VALUES(144,'LIV','2026-summer','Bradley Barcola','바르콜라','바르콜라',NULL,NULL,'PSG','LW','LW','HIGH','2026-08-12','46211X5111411013100110000',NULL,NULL,39,7.089999999999999858,'w_wideplm','Build-Up','w_wideplm','Build-Up',0.9060000000000000275,'[2026-08-12 상향] Romano(1티어, 08-10): **"리버풀이 공식 구단 간 협상을 시작했다"** · **"매일 협상 중(active talks in daily talks)"** · **"개인 조건은 전혀 문제가 아니다"**. Sky 원기사도 확정 — **08-07 Vinny O''Connor·Amar Mehta**(예비 회담 완료, PSG 평가액 £145m) 및 **07-29**(오프닝 오퍼 준비). ⚠️ Fotmob 라벨 ''Sky Sports/08-08''은 **출처는 정확, 날짜가 하루 오차**였다. 금액: 리버풀 ~€100m(£86m) → BBC 기준 £100m까지 상향 의사 vs PSG 요구 **€150m**(초기 €170m). 선수는 PSG 재계약을 거부했고 이라올라가 출전시간을 약속, 이적 희망 명확. [경쟁구도] 아스날 하이잭설은 The Sun(3티어) 단독이라 채택 불가 — **리버풀 단독 우위**. PSG는 Akliouche 영입 합의(08-01 Romano, £42.8m)로 스쿼드가 포화돼 방출 여건은 갖춰졌다. [2026-08-13 단계 변화 없음 — §2-0 함정 회피] 오늘 검색 상위를 "리버풀 £98.5m(€115m) **입찰 제출**" 헤드라인이 도배하나 추적 결과 **전부 L''Équipe(Loïc Tanzi) 08-07 보도의 재인용**이고 원문조차 "제출할 예정(set to submit)"이었다. ⭐ 그 뒤 **Romano(1티어) 08-10이 명시적으로 부인** — "리버풀은 PSG에 **공식 입찰을 보내지 않았다**. 공식 구단 간 협상을 시작하고 숫자를 제시(indicated)했을 뿐이며 PSG 요구액과는 여전히 멀다." 08-10 > 08-07이므로 **Romano 판이 유효**하다. ⚠️ ESPN(1티어) "Liverpool to bid for Barcola"도 **07-29자**였다. **신규 사실(단계 변화 아님)**: **알-켈라이피 PSG 회장이 08-12 슈퍼컵(PSG 2-1 아스톤 빌라) 직후 Canal+에 직접 발언** — "떠날지는 말할 수 없다. 오늘은 PSG 선수다. 두고 보자." 매각 부인이 아니라 **문을 열어둔 비확약 발언**이다. 금액 구도 불변: 리버풀 €100m대 vs PSG €150m 초과 요구.','Fabrizio Romano (2026-08-10) via football365.com/news/bradley-barcola-liverpool-paris-saint-germain-fabrizio-romano-transfer-update ; Sky Sports Vinny O''Connor·Amar Mehta (2026-08-07) skysports.com/football/news/11669/13570766 ; Sky (2026-07-29) 11095/13567997 ; Sky 영상 Mark McAdam (08-11)','HIGH — §2 기준 ''1티어가 협상 단계를 보도''를 충족한다(Romano ''공식 구단 간 협상''). ⚠️ 다만 **공식 오퍼는 0건**이고 금액 갭이 €50m로 크다 — 등급은 ''보도된 단계''를 재는 것이지 성사 확률이 아니다. Romano 본인이 ''리버풀이 공식 입찰을 보냈다는 보도는 사실이 아니다''라고 부인했다. ⚠️ **스쿼드 밸런스 반론 존재**: Carragher(Sky) — ''바르콜라는 반대쪽 윙이고 리버풀에 필요한 건 우측 윙어''. 실제로 리버풀은 시니어 우측 윙어가 전무하다(선덜랜드 친선에서 19세 Kieran Morrison 기용). ⚠️ 실측 PENDING — SofaScore 68경기 수집 완료, 슬롯 판정·집계 미수행. ⚠️ 이 표본은 **PSG 소속**이고 이라올라 체제가 아니다(불변규칙 7 · obs#157). | [실측 완료 2026-08-12] SofaScore 25/26 전수 68경기 중 45분+ 46경기. ⭐ **좌우 분리 적용**(obs#156 교훈) — 46경기 중 **7경기가 우측**이라 혼합 그리드는 좌우를 섞는다. **좌측 39경기만** 집계했다(좌2컬럼 0.78). 혼합 집계는 .873으로 Δ.033 낮다. 참고: 우측 7경기만 재면 RW에서 w_winger/Versatile .806 — 양쪽 다 가능한 자원이다. ⚠️ 표본은 **PSG** 소속이고 이라올라 체제가 아니다(obs#157).');
INSERT INTO transfer_targets VALUES(145,'LIV','2026-summer','Ibrahim Mbaye','음바예','음바예',86,NULL,'PSG','RW','RM','MEDIUM-HIGH','2026-08-06','011231115X100261001300000',74.4200000000000017,64.9200000000000017,16,7.009999999999999787,'wm_widemid','Build-Up','wm_widemid','Build-Up',0.8780000000000000026,'[2026-08-12 신규] Romano(1티어) 직접 발언: "이브라힘 음바예에 대한 진짜 관심이 있다. 선수의 새 에이전트 호르헤 멘데스와 대화가 있다. 레버쿠젠이 밀어붙였지만 **지금은 리버풀이 선두**다." 추정 €50m. ⭐ **결손 칸 정합**: 리버풀은 살라(→트라브존스포르 08-06) 이탈 후 **시니어 우측 윙어가 전무**하다(선덜랜드 친선에서 19세 Kieran Morrison 기용). 음바예는 주로 우측을 뛴다. [경쟁구도] 레버쿠젠이 앞서 있었으나 Romano 기준 **리버풀이 선두로 역전**. 바르콜라 건과 독립적이라 둘 다 성사 가능하다(좌·우 다른 칸). ⚠️ 어제 이 이름을 ''TEAMtalk 3티어''로 보류했는데 **TEAMtalk은 Romano 발언의 전달 매체**였다 — 실질 출처는 1티어다. 애그리게이터의 원출처를 추적하라는 §2 규칙이 실제로 등급을 바꾼 사례. [2026-08-13 1티어 보강, 단계 불변] **Sky Sports 공식 기사(1티어) 확보** — Mark McAdam·Vinny O''Connor, 2026-08-06: "리버풀이 딜 조건을 **타진**했으나 음바예·바르콜라 **양쪽 모두 정식 오퍼는 아직 없다**". PSG 평가액 £35m 안팎. ⚠️ Sky(08-06)가 Romano(08-11 "지금은 리버풀이 선두")보다 **앞서므로 최신 단계는 여전히 Romano 판**이다 — 등급 변경 근거가 아니라 출처 보강이다. [2026-08-13 슬롯 규약 교정] 45분+·hit_points>=15 중 우2열 합이 좌2열 합보다 큰 16경기(1003분) 표본은 유지. RM에서 실행 가능한 WM군 제한 argmax는 wm_widemid/Build-Up .878이다. 종전 w_wideplm/Build-Up .940은 순수 W군 참고값으로만 보존한다.','Fabrizio Romano 발언 (2026-08-06) via teamtalk.com/liverpool/ibrahim-mbaye-bradley-barcola-liverpool-psg-fabrizio-romano-latest ; Sky Sports 병기 확인 ; 리드 Fotmob teamIds=8650 (08-07 TEAMtalk) ; Sky Sports(1티어) 2026-08-06 https://www.skysports.com/football/news/11669/13569955/ibrahim-mbaye-liverpool-explore-deal-for-paris-saint-germain-winger','MEDIUM-HIGH — 1티어(Romano) 관심 보도 + ''선두'' 언급. §2-0 검증 통과: 나이 18세 표기가 실제와 일치. ⚠️ 오퍼·협상 단계 보도 0건이라 HIGH 아님. ⚠️ **실측 PENDING** — SofaScore 미수집. ⚠️ 18세라 표본이 얕을 수 있다(다음 회차 수집 시 45분+ 경기 수 확인 필요). | [실측 전수 완료 2026-08-12] 2026-08-12 전수 실측(SofaScore 25/26). 종전 6경기 표본을 대체하지 않고 추가한다(불변규칙 2). ⚠️ 표본은 **이전/현 소속 클럽**의 것이고 우리 팀 전술이 아니다(obs#157·#158). 20경기 중 **4경기가 좌측**이라 obs#156 교훈대로 **우측 16경기만** 집계. 표본은 PSG. 45분+ 16경기(1003분) 집계.');
INSERT INTO transfer_targets VALUES(146,'LIV','2026-summer','Ronald Araújo','아라우호','아라우호',NULL,NULL,'Barcelona → Liverpool (임대)','CB','RCB','CONFIRMED','2026-08-11','001000012101594015X400232',NULL,NULL,22,7.150000000000000355,'cb_bpd','Aggressive','cb_bpd','Aggressive',0.9080000000000000293,'[2026-08-12] **리버풀 구단 공식 발표(2026-08-11)** — 바르셀로나에서 **26/27 시즌 임대**(취업허가·국제이적동의 조건부), 등번호 33. **매입 옵션 약 €55m(£47.14m)**, 임대료 없음·전액 급여 부담, 선수가 감봉을 수용했다. ⭐ **코나테(→레알 06-18 자유이적) 이탈 뒤의 센터백 보강**이다. 다만 기사들은 이를 **부상 공백(고메스·레오니·자케)에 대한 단기 시장 기회**로 규정한다 — 리버풀의 여름 우선순위는 센터백이 아니라 **와이드 포워드**였다. [경쟁구도] 단독.','Liverpool 구단 공식 https://www.liverpoolfc.com/news/liverpool-agree-deal-sign-ronald-araujo-loan (2026-08-11) ; Sky Sports https://www.skysports.com/football/news/11669/13570899 (08-11) ; ESPN https://www.espn.com/soccer/story/_/id/49556442 (08-11) ; 리드 TransferFeed liverpool/8','CONFIRMED — 구단 공식 발표. §2-0 검증 통과: 본문 나이 27세(1999-03-07생)가 일치하고 병기 상황(테어 슈테겐 이탈 후 주장단, 플릭 체제 출전시간, 이라올라 부임)이 26/27 창과 정합. ⚠️ **실측 PENDING** — SofaScore 미수집이라 그리드·적합이 없다. 다음 회차에 수집해 `squad_entries` regime_id=3으로 승격할 것. ⚠️ 승격 시 표본은 **바르셀로나** 소속이므로 `grid_club` 캐비앗(obs#157) 대상이다. | [실측 전수 완료 2026-08-12] 2026-08-12 전수 실측(SofaScore 25/26). 종전 6경기 표본을 대체하지 않고 추가한다(불변규칙 2). ⚠️ 표본은 **이전/현 소속 클럽**의 것이고 우리 팀 전술이 아니다(obs#157·#158). **22/22 전 경기 우측 우세**(우2 0.69). LCB로 재면 .271로 붕괴 — **RCB 전용 자원**이다. 표본은 바르셀로나. 45분+ 22경기(1615분) 집계.');
INSERT INTO transfer_targets VALUES(147,'AVL','2026-summer','Aaron Wan-Bissaka','완비사카','완비사카',NULL,863653,'West Ham United','RB','RB','MEDIUM-HIGH','2026-08-12','000140002X001290003900234',83.75,46.14000000000000056,25,6.589999999999999858,'fb_att_wb','Support','fb_att_wb','Support',0.93200000000000005,'캐시의 유일 백업 부재를 메우는 RB 후보. 에머슨 로열 무산(STALE 전환) 이후 **RB 후보가 0이던 결손 칸**에 정확히 대응한다(안드레스 가르시아→헤타페, 네델코비치 20세는 에메리 구상 밖·레인저스 관심). The Athletic(1티어) 08-12: 빌라가 웨스트햄과 **회담 개시**. 웨스트햄 평가액 £25m, 계약 2031까지. 웨스트햄은 25/26 강등 후 매각 용의가 있으나 페르난드스·서머빌·포츠 매각으로 £150m+를 확보해 **저가 오퍼를 받을 압박이 없다**. [경쟁구도 2026-08-13] 아스날·에버턴·페네르바체 관심이 병기되나 **단계 보도는 빌라만**(에버턴은 셀틱 존스턴으로 선회). 선수는 PL 잔류 희망. 판정 **빌라 우위**. 병목은 경쟁이 아니라 £25m 호가와 협상 초기 단계. [실측 2026-08-13] SofaScore 863653, 25/26 클럽 경기(웨스트햄 PL+FA컵) 45분+·히트포인트 15+ **25경기 2149분** 균등가중. 중심 툴좌표 (83.75, 46.14) = 우측·중앙 높이. 평균 평점 6.59. **RB(x=87) 커널 적합 fb_att_wb/Support .932** — 에머슨 로열 .950과 동급이고 루헤리 LB .949의 우측 대응물이다. ⭐ **좌우 혼입 없음**: 25/25 전 경기 우측 우세, 우2컬럼 평균 **91.7%**(최저 71.2%) — obs#156(바르콜라) 교훈에 따른 좌우 분리 검사 통과. LB로 재면 .022로 붕괴해 **코사인이 방향을 실제로 본다**(obs#127의 대칭 슬롯 맹점은 FB에 적용되지 않는다). [처방] opt=fit=fb_att_wb/Support(.932) — 규약대로 실측 argmax.','The Athletic(1티어, 2026-08-12, "opened talks"·preliminary) 경유 https://www.goal.com/en/lists/aston-villa-aaron-wan-bissaka-transfer-west-ham-manchester-united/blt64cc0a3ed802e9f8 (2026-08-13) ; Alex Crook/talkSPORT(2티어) https://www.livescore.com/en/news/football/premier-league/aston-villa-explore-move-for-aaron-wan-bissaka-as-west-ham-set-25-asking-price-claret-villans/ ; 실측 SofaScore player 863653','MEDIUM-HIGH — 1티어(The Athletic)가 회담 개시를 보도하나 문구가 **"preliminary/exploratory"**라 §2 등급표의 HIGH 요건("advanced talks"·합의)에 미달한다. ⚠️ The Athletic 원문은 페이월로 직접 확인 실패 — Goal·LiveScore 인용문에 의존했다. §2-0 발행일 검증 통과: 나이 28세 표기 일치(1997-11생) · 병기 상황 전건 현 창 정합(웨스트햄 강등, 디뉴→PSG, 루헤리 진행 중, 에머슨 로열 무산, 워커-피터스에 밀린 출전 기록). ⚠️ 표본은 **웨스트햄(강등팀)의 것**이며 빌라 전술이 아니다(obs#157·#158) — 팀을 옮기면 좌우 위치가 17~18단위 움직인 사례가 둘 있다. ⚠️ 26세 이상 자원이라 리세일 가치는 낮다.');
